fn collect_comment_ranges(node: Node, out: &mut Vec<(usize, usize)>) {
    if is_comment(&node) {
        out.push((node.start_byte(), node.end_byte()));
        return;
    }
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        collect_comment_ranges(child, out);
    }
}

